import numpy as np

def problem(x: np.ndarray) -> float:
    dim = x.shape[0]
    linear_term = np.sum(np.array([0.1, 0.2, 0.4]) * x)
    quadratic_term = np.sum(np.array([0.3, 0.05, 0.2]) * (x**2))
    interaction_term = 0
    for i in range(dim):
        for j in range(i + 1, dim):
            interaction_term += 0.03 * x[i] * x[j]
    skewness_term = 0.2 * np.sum(x**3)
    gaussian_mod = np.exp(-0.1 * np.sum(x**2))
    dimension_scale = np.array([1.2, 0.8, 1.0])[:dim]  # Truncate if dim < 3
    return gaussian_mod * (linear_term + quadratic_term + interaction_term + skewness_term) * np.sum(dimension_scale)

import numpy as np

def problem(x: np.ndarray) -> float:
    dim = x.shape[0]
    f = np.sum(0.3 * x) + np.sum(0.2 * x**2)
    for i in range(dim):
        for j in range(i + 1, dim):
            f += 0.03 * x[i] * x[j]
    f += 0.05 * np.sum(x**3) + 0.05 * np.sin(np.sum(x)) + 1.0
    return f

import numpy as np

def problem(x: np.ndarray) -> float:
    dim = x.shape[0]
    linear_term = np.sum(0.7 * x)
    quadratic_term = np.sum(0.2 * (x**2))
    cubic_term = 0.02 * np.sum(x**3)

    sinusoidal_term = 0.15 * np.sum(np.sin(2*x))

    exponential_term = 0.03 * np.exp(0.1 * np.sum(x))

    interaction_term = 0.0
    for i in range(dim):
        for j in range(i + 1, dim):
            interaction_term += 0.01 * x[i] * x[j]

    log_barrier = 0.0
    for i in range(dim):
        if x[i] <= -5 or x[i] >= 5 :
            return float('inf')
        log_barrier += -0.005 * np.log(5 - x[i]) -0.005 * np.log(5 + x[i])

    objective_value = linear_term + quadratic_term + cubic_term +  sinusoidal_term + exponential_term + interaction_term + log_barrier + 2.0
    return objective_value
